-- GIV-3A LOCAL BUILD ONLY. No secret, grant, network transport, charge or live activation.
create function private.payments_permissions() returns text[] language sql immutable set search_path='' as $$select array['payments.view','payments.configure','payments.route','payments.refund','payments.void','payments.recurring.manage','payments.provider.activate']::text[]$$;
do $$declare keys text[];begin
 keys:=private.staff_permission_keys()||private.payments_permissions();
 alter table public.organization_staff_permissions drop constraint organization_staff_permissions_permission_check;
 execute format('alter table public.organization_staff_permissions add constraint organization_staff_permissions_permission_check check(permission=any(%L::text[]))',keys);
 execute format('create or replace function private.staff_permission_keys() returns text[] language sql immutable set search_path='''' as %L','select '||quote_literal(keys)||'::text[]');
end$$;
alter table public.giving_recurring_instructions drop constraint giving_recurring_instructions_frequency_check;
alter table public.giving_recurring_instructions add constraint giving_recurring_instructions_frequency_check check(frequency in('weekly','biweekly','monthly','annual','twice_monthly','custom'));
-- Retain legacy placeholder provider codes for compatibility; new native records use only four codes.
alter table public.giving_gateway_accounts drop constraint giving_gateway_accounts_provider_check;
alter table public.giving_gateway_accounts add constraint giving_gateway_accounts_provider_check check(provider in('nmi','authorize_net','manual','future','stripe_connect','paypal','square','external_connector'));
alter table public.giving_gateway_accounts add column configuration_status text not null default 'missing' check(configuration_status in('missing','configured','invalid','held')),add column last_verified_at timestamptz;
alter table public.giving_processor_routes add column provider_route_key text,add column external_processor_id text,add column currency text not null default 'USD' check(currency ~ '^[A-Z]{3}$'),add column country text not null default 'US' check(country ~ '^[A-Z]{2}$'),add column payments_enabled boolean not null default false check(not payments_enabled),add column environment text not null default 'sandbox' check(environment in('sandbox','live'));
create unique index payments_provider_route_key on public.giving_processor_routes(gateway_id,provider_route_key) where provider_route_key is not null;
alter table public.giving_sessions add column expires_at timestamptz not null default (now()+interval '30 minutes');
alter table public.giving_session_lines alter column fund_id drop not null;
alter table public.giving_session_lines add column payment_purpose text check(payment_purpose in('charitable_contribution','event_fee','registration_fee','merchandise','deposit','camp_fee','other_payment')),add column form_version_id uuid references public.platform_form_versions(id);
alter table public.giving_session_lines add constraint payments_non_gift_tax check(payment_purpose='charitable_contribution' or not tax_eligible),add constraint payments_gift_designation check(payment_purpose<>'charitable_contribution' or fund_id is not null);
create table private.payments_control(singleton boolean primary key default true check(singleton),payments_enabled_global boolean not null default false check(not payments_enabled_global));
insert into private.payments_control values(true,false);
create table private.payments_platform_authority(user_id uuid primary key references auth.users(id),active boolean not null default false,effective_at timestamptz not null default now(),expires_at timestamptz not null,reason text not null,check(expires_at>effective_at));
create table private.payments_org_control(organization_id uuid primary key references public.organizations(id),enabled boolean not null default false check(not enabled));
create table private.payments_gateway_bindings(organization_id uuid not null,gateway_id uuid primary key,environment text not null check(environment in('sandbox','live')),credential_reference text not null check(credential_reference ~ '^payments/[a-f0-9-]{36}/[a-f0-9-]{36}/(sandbox|live)/v[0-9]+$'),secret_version int not null check(secret_version>0),check(credential_reference='payments/'||organization_id::text||'/'||gateway_id::text||'/'||environment||'/v'||secret_version::text),webhook_reference text check(webhook_reference ~ '^payments/[a-f0-9-]{36}/[a-f0-9-]{36}/(sandbox|live)/webhook/v[0-9]+$'),foreign key(organization_id,gateway_id) references public.giving_gateway_accounts(organization_id,id));
-- Logical donor method has only a masked descriptor. Provider/customer/payment refs stay in existing private profiles.
create table private.payments_methods(id uuid primary key default gen_random_uuid(),organization_id uuid not null,person_id uuid not null,brand text not null check(brand in('Visa','Mastercard','American Express','Discover','Bank','Other')),last4 text not null check(last4 ~ '^[0-9]{4}$'),expiry_month int check(expiry_month between 1 and 12),expiry_year int check(expiry_year between 2000 and 2200),billing_name text check(length(billing_name)<=100),status text not null default 'held' check(status in('held','active','removed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,person_id) references public.organization_people(organization_id,id),unique(organization_id,id),unique(organization_id,person_id,id));
create table private.payments_customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null,person_id uuid not null,gateway_id uuid not null,environment text not null check(environment in('sandbox','live')),provider_customer_reference text not null check(provider_customer_reference ~ '^synth:[A-Za-z0-9:_-]{1,120}$'),created_at timestamptz not null default now(),foreign key(organization_id,person_id) references public.organization_people(organization_id,id),foreign key(organization_id,gateway_id) references public.giving_gateway_accounts(organization_id,id),unique(organization_id,gateway_id,environment,person_id),unique(organization_id,gateway_id,environment,provider_customer_reference));
alter table private.giving_payment_profiles add column logical_method_id uuid,add column environment text not null default 'sandbox' check(environment in('sandbox','live')),add column reference_status text not null default 'held' check(reference_status in('held','active','removed')),add column created_at timestamptz not null default now(),add column updated_at timestamptz not null default now(),add foreign key(organization_id,person_id,logical_method_id) references private.payments_methods(organization_id,person_id,id),add unique(organization_id,gateway_id,id);
create table private.payments_token_routes(organization_id uuid not null,profile_id uuid not null,gateway_id uuid not null,route_id uuid not null,primary key(profile_id,route_id),foreign key(organization_id,gateway_id,profile_id) references private.giving_payment_profiles(organization_id,gateway_id,id),foreign key(organization_id,gateway_id,route_id) references public.giving_processor_routes(organization_id,gateway_id,id));
create table private.payments_checkout_context(session_id uuid primary key,organization_id uuid not null,form_version_id uuid,form_enabled boolean not null default false check(not form_enabled),receipt_email text check(length(receipt_email)<=254 and receipt_email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'),recurring_choice text not null default 'once' check(recurring_choice in('once','weekly','biweekly','monthly','annual')),foreign key(organization_id,session_id) references public.giving_sessions(organization_id,id),foreign key(organization_id,form_version_id) references public.platform_form_versions(organization_id,id));
create table private.payments_operations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,leg_id uuid not null,gateway_id uuid not null,operation text not null check(operation in('tokenization','customer','attach','authorize','capture','sale','void','refund','recurring_create','recurring_update','recurring_cancel','transaction','settlement')),request_key uuid not null,payload_digest text not null,amount_minor bigint not null check(amount_minor between 1 and 1000000000000),refund_id uuid references public.giving_refunds(id),status text not null default 'held' check(status in('held','pending','review','completed','failed')),lease_token uuid,lease_created_at timestamptz,created_at timestamptz not null default now(),foreign key(organization_id,leg_id) references public.giving_transaction_legs(organization_id,id),foreign key(organization_id,gateway_id) references public.giving_gateway_accounts(organization_id,id),unique(organization_id,id),unique(organization_id,operation,request_key));
create table private.payments_journal(id uuid primary key default gen_random_uuid(),organization_id uuid not null,operation_id uuid not null,provider text not null,route_id uuid not null,state text not null check(state in('held','claimed','pending','authorized','captured','settled','failed','voided','partially_refunded','refunded','review')),failure_category text check(failure_category in('declined','insufficient_funds','invalid_payment_method','expired_card','processor_unavailable','fraud_review','routing_error','configuration_error','duplicate','unknown')),provider_request_reference text check(provider_request_reference ~ '^synth:[A-Za-z0-9:_-]{1,120}$'),started_at timestamptz not null default now(),completed_at timestamptz,foreign key(organization_id,operation_id) references private.payments_operations(organization_id,id),foreign key(organization_id,route_id) references public.giving_processor_routes(organization_id,id));
create index payments_journal_operation on private.payments_journal(operation_id,started_at,id);
create table private.payments_webhooks(id uuid primary key default gen_random_uuid(),organization_id uuid not null,gateway_id uuid not null,route_id uuid not null,leg_id uuid not null,event_reference text not null check(event_reference ~ '^synth:[A-Za-z0-9:_-]{1,120}$'),body_digest text not null check(body_digest ~ '^[a-f0-9]{64}$'),normalized_status text not null check(normalized_status in('pending','authorized','captured','settled','failed','voided','refunded','review','disputed')),reconciliation_state text not null default 'held' check(reconciliation_state='held'),created_at timestamptz not null default now(),foreign key(organization_id,gateway_id,route_id) references public.giving_processor_routes(organization_id,gateway_id,id),foreign key(organization_id,leg_id) references public.giving_transaction_legs(organization_id,id),unique(gateway_id,event_reference));
create table private.payments_settlements(id uuid primary key default gen_random_uuid(),organization_id uuid not null,gateway_id uuid not null,route_id uuid not null,provider_batch_reference text not null check(provider_batch_reference ~ '^synth:[A-Za-z0-9:_-]{1,120}$'),payload_digest text not null,settlement_date date not null,currency text not null check(currency ~ '^[A-Z]{3}$'),gross_minor bigint not null check(gross_minor>=0),fee_minor bigint check(fee_minor>=0),net_minor bigint,transaction_count int not null check(transaction_count>=0),state text not null default 'held' check(state='held'),foreign key(organization_id,gateway_id,route_id) references public.giving_processor_routes(organization_id,gateway_id,id),unique(gateway_id,route_id,provider_batch_reference),check(net_minor is null or fee_minor is not null and net_minor=gross_minor-fee_minor));
create table private.payments_recurring_routes(organization_id uuid not null,instruction_id uuid not null,route_id uuid not null,profile_id uuid,provider_schedule_reference text check(provider_schedule_reference ~ '^synth:[A-Za-z0-9:_-]{1,120}$'),state text not null default 'held' check(state='held'),primary key(instruction_id,route_id),foreign key(organization_id,instruction_id) references public.giving_recurring_instructions(organization_id,id),foreign key(organization_id,route_id) references public.giving_processor_routes(organization_id,id),foreign key(organization_id,profile_id) references private.giving_payment_profiles(organization_id,id));
create table private.payments_recurring_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null,instruction_id uuid not null,scheduled_at timestamptz not null,lease_token uuid not null default gen_random_uuid(),state text not null default 'held' check(state='held'),created_at timestamptz not null default now(),foreign key(organization_id,instruction_id) references public.giving_recurring_instructions(organization_id,id),unique(instruction_id,scheduled_at));
-- Every new table is denied raw access, including service callers. Workers use guarded RPCs.
do $$declare r record;begin for r in select tablename from pg_tables where schemaname='private' and tablename like 'payments_%'loop execute format('alter table private.%I enable row level security',r.tablename);execute format('revoke all on private.%I from public,anon,authenticated,service_role',r.tablename);end loop;end$$;
do $$declare t text;begin foreach t in array array['payments_journal','payments_webhooks','payments_settlements','payments_checkout_context','payments_token_routes','payments_recurring_routes','payments_recurring_jobs']loop execute format('create trigger payments_history_immutable before update or delete on private.%I for each row execute function private.giving_immutable()',t);end loop;end$$;
create function private.payments_require(o uuid,k text) returns void language plpgsql security definer set search_path='' as $$begin if not private.giving_authorized(o,k)then raise exception 'Payment access unavailable' using errcode='42501';end if;end$$;
create function private.payments_owned(o uuid,person uuid) returns boolean language sql volatile security definer set search_path='' as $$select private.outreach_verified(auth.uid()) and exists(select 1 from private.giving_donor_account_links where organization_id=o and person_id=person and user_id=auth.uid() and active)$$;
create function private.payments_method_summary(o uuid,person uuid default null) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'person_id',m.person_id,'brand',m.brand,'last4',m.last4,'expiry_month',m.expiry_month,'expiry_year',m.expiry_year,'status',m.status,'gateway_count',(select count(distinct gateway_id) from private.giving_payment_profiles where organization_id=o and logical_method_id=m.id and reference_status<>'removed'))order by m.created_at),'[]')from private.payments_methods m where m.organization_id=o and (person is null or m.person_id=person)$$;
create function private.payments_route(o uuid,fund uuid,destination uuid,purpose text,currency text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare d public.giving_destinations;g public.giving_gateway_accounts;r public.giving_processor_routes;f public.giving_funds;begin
 if purpose not in('charitable_contribution','event_fee','registration_fee','merchandise','deposit','camp_fee','other_payment') or purpose is null then raise exception 'Payment purpose required';end if;
 if fund is not null then select * into f from public.giving_funds where organization_id=o and id=fund and status='active' and (starts_on is null or starts_on<=current_date)and(ends_on is null or ends_on>=current_date);if not found then raise exception 'Designation unavailable';end if;destination:=f.destination_id;
 elsif purpose='charitable_contribution' then raise exception 'Contribution requires fund';end if;
 select * into d from public.giving_destinations where organization_id=o and id=destination and active;
 if not found or d.currency<>currency then raise exception 'Destination/currency unavailable';end if;
 select * into g from public.giving_gateway_accounts where organization_id=o and id=d.gateway_id;
 select * into r from public.giving_processor_routes where organization_id=o and id=d.processor_route_id and gateway_id=g.id and active;
 if not found or g.provider not in('nmi','authorize_net','manual','future') or r.currency<>currency or r.environment<>g.environment then raise exception 'Deterministic currency/environment route unavailable';end if;
 return jsonb_build_object('destination_id',d.id,'destination_revision',d.revision,'destination_label',d.merchant_label,'gateway_id',g.id,'gateway_revision',g.revision,'provider',g.provider,'environment',g.environment,'processor_route_id',r.id,'processor_revision',r.revision,'route_label',r.label,'provider_route_key',coalesce(r.provider_route_key,r.processor_reference),'external_processor_id',r.external_processor_id,'currency',currency,'country',r.country,'fund_id',fund,'fund_revision',f.revision,'fund_label',f.name,'payment_purpose',purpose,'consolidation_allowed',not('no_consolidation'=any(r.capabilities)));
end$$;
create function private.payments_actor_current(o uuid,u uuid)returns boolean language sql stable security definer set search_path=''as $$select exists(select 1 from public.organization_staff_directory d join public.organization_staff_permissions p on p.organization_id=d.organization_id and p.user_id=d.user_id join auth.users a on a.id=d.user_id where d.organization_id=o and d.user_id=u and d.active and d.effective_at<=now() and(d.expires_at is null or d.expires_at>now())and p.permission='payments.view'and p.revoked_at is null and p.department_ids is null and p.effective_at<=now()and(p.expires_at is null or p.expires_at>now())and a.email_confirmed_at is not null and not coalesce(a.is_anonymous,false))$$;
create function private.payments_gate(o uuid,leg_id uuid,method_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare l public.giving_transaction_legs;s public.giving_sessions;g public.giving_gateway_accounts;r public.giving_processor_routes;b private.payments_gateway_bindings;ctx private.payments_checkout_context;compatible boolean;begin
 select * into l from public.giving_transaction_legs where organization_id=o and id=leg_id;
 if not found then raise exception 'Transaction unavailable' using errcode='42501';end if;
 select * into s from public.giving_sessions where organization_id=o and id=l.session_id;
 select * into g from public.giving_gateway_accounts where organization_id=o and id=(l.route_snapshot->>'gateway_id')::uuid;
 select * into r from public.giving_processor_routes where organization_id=o and id=(l.route_snapshot->>'processor_route_id')::uuid and gateway_id=g.id;
 select * into b from private.payments_gateway_bindings where organization_id=o and gateway_id=g.id and environment=g.environment;
 select * into ctx from private.payments_checkout_context where organization_id=o and session_id=s.id;
 compatible:=exists(select 1 from private.giving_payment_profiles p join private.payments_token_routes tr on tr.profile_id=p.id and tr.gateway_id=p.gateway_id where p.organization_id=o and p.logical_method_id=method_id and p.person_id=s.person_id and p.gateway_id=g.id and p.environment=g.environment and p.active and p.reference_status='active' and tr.route_id=r.id);
 return jsonb_build_object('execution_allowed',false,'stage_enabled',false,'global_enabled',(select payments_enabled_global from private.payments_control),'organization_enabled',coalesce((select enabled from private.payments_org_control where organization_id=o),false),'gateway_enabled',coalesce(g.enabled,false),'route_enabled',coalesce(r.payments_enabled,false),'form_enabled',coalesce(ctx.form_enabled,false),'environment_matches',g.environment=l.route_snapshot->>'environment' and r.environment=g.environment,'route_matches',r.id::text=l.route_snapshot->>'processor_route_id' and r.gateway_id=g.id and r.active,'amount_valid',l.amount_minor between 1 and 1000000000000 and l.currency=r.currency,'token_compatible',compatible,'credentials_configured',b.gateway_id is not null,'initiator_authorized',case when s.created_by is not null then private.payments_actor_current(o,s.created_by)else false end,'provider_capability_verified',g.configuration_status='configured'and g.last_verified_at is not null,'session_current',s.expires_at>now(),'message','Payment processing is not yet enabled.');
end$$;
-- Use existing Giving sessions/legs/lines/requests. No parallel payment balance or ledger.
create function private.payments_prepare(o uuid,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare previous public.giving_requests;identifier uuid;leg uuid;line jsonb;route jsonb;routekey text;amount bigint;total bigint:=0;purpose text;begin
 perform private.giving_payload(p,array['request_key','person_id','household_id','anonymous_public','receipt_email','currency','intended_minor','source','campaign_reference','event_reference','recurring_choice','form_version_id','lines']);
 if p->>'request_key' is null or p->>'currency' !~ '^[A-Z]{3}$' or jsonb_typeof(p->'lines')<>'array' or jsonb_array_length(p->'lines') not between 1 and 30 then raise exception 'Bounded checkout required';end if;
 select * into previous from public.giving_requests where organization_id=o and operation='payments.checkout' and request_key=(p->>'request_key')::uuid;
 if found then if previous.payload<>p then raise exception 'Checkout idempotency conflict'using errcode='PT409';end if;return previous.result;end if;
 perform private.giving_identity(o,(p->>'person_id')::uuid,(p->>'household_id')::uuid);
 if p->>'form_version_id' is not null then
 if not private.forms_can(o,'forms.read',(select form_id from public.platform_form_versions where organization_id=o and id=(p->>'form_version_id')::uuid))then raise exception 'Form unavailable'using errcode='42501';end if;
 if not exists(select 1 from public.platform_form_versions where organization_id=o and id=(p->>'form_version_id')::uuid and state='published')then raise exception 'Published form required';end if;end if;
 if p->>'intended_minor' !~ '^[0-9]{1,13}$' then raise exception 'Exact minor units required';end if;
 insert into public.giving_sessions(organization_id,person_id,household_id,anonymous_public,currency,intended_minor,source,campaign_reference,event_reference,request_key,created_by)
 values(o,(p->>'person_id')::uuid,(p->>'household_id')::uuid,coalesce((p->>'anonymous_public')::boolean,false),p->>'currency',(p->>'intended_minor')::bigint,'native_checkout',p->>'campaign_reference',p->>'event_reference',(p->>'request_key')::uuid,auth.uid())returning id into identifier;
 perform set_config('giving.build_session','on',true);
 for line in select value from jsonb_array_elements(p->'lines')loop
 perform private.giving_payload(line,array['fund_id','destination_id','amount_minor','purpose','campaign_reference','event_reference']);
 if line->>'amount_minor' !~ '^[0-9]{1,13}$' then raise exception 'Exact line amount required';end if;amount:=(line->>'amount_minor')::bigint;if amount not between 1 and 1000000000000 then raise exception 'Line amount outside bounds';end if;
 purpose:=line->>'purpose';if p->>'form_version_id'is not null and purpose is distinct from(select case classification when 'donation'then 'charitable_contribution'when 'purchase'then 'merchandise'else classification end from public.platform_form_payments where version_id=(p->>'form_version_id')::uuid)then raise exception 'Form payment purpose cannot be changed';end if;route:=private.payments_route(o,(line->>'fund_id')::uuid,(line->>'destination_id')::uuid,purpose,p->>'currency');
 routekey:=concat(route->>'destination_id',':',route->>'gateway_id',':',route->>'processor_route_id',case when (route->>'consolidation_allowed')::boolean then '' else ':'||gen_random_uuid()::text end);
 insert into public.giving_transaction_legs(organization_id,session_id,amount_minor,route_snapshot,route_key,currency)values(o,identifier,amount,route-'payment_purpose'-'fund_id'-'fund_revision'-'fund_label',routekey,p->>'currency')on conflict(session_id,route_key)do update set amount_minor=giving_transaction_legs.amount_minor+excluded.amount_minor returning id into leg;
 insert into public.giving_session_lines(organization_id,session_id,leg_id,fund_id,amount_minor,route_snapshot,tax_eligible,campaign_reference,event_reference,payment_purpose,form_version_id)
 values(o,identifier,leg,(line->>'fund_id')::uuid,amount,route,purpose='charitable_contribution' and coalesce((select tax_eligible from public.giving_funds where organization_id=o and id=(line->>'fund_id')::uuid),false),coalesce(line->>'campaign_reference',p->>'campaign_reference'),coalesce(line->>'event_reference',p->>'event_reference'),purpose,(p->>'form_version_id')::uuid);total:=total+amount;end loop;
 perform set_config('giving.build_session','off',true);if total<>(p->>'intended_minor')::bigint then raise exception 'Checkout lines do not equal total';end if;
 insert into private.payments_checkout_context(session_id,organization_id,form_version_id,receipt_email,recurring_choice)values(identifier,o,(p->>'form_version_id')::uuid,p->>'receipt_email',coalesce(p->>'recurring_choice','once'));
 insert into public.giving_requests values(o,'payments.checkout',(p->>'request_key')::uuid,p,jsonb_build_object('id',identifier,'execution','held'),now());
 perform private.giving_audit_event(o,'payments.checkout.prepared',identifier);return jsonb_build_object('id',identifier,'execution','held');
end$$;
-- Accepted pre-GIV-3A Form lines remain immutable; derive legacy purpose from their original submission version.
create function private.payments_line_purpose(l public.giving_session_lines)returns text language sql stable security definer set search_path=''as $$select coalesce(l.payment_purpose,(select case p.classification when 'donation'then 'charitable_contribution'when 'purchase'then 'merchandise'else p.classification end from public.platform_form_submissions s join public.platform_form_payments p on p.version_id=s.version_id where s.organization_id=l.organization_id and s.giving_session_id=l.session_id order by s.submitted_at,s.id limit 1),'charitable_contribution')$$;
create function private.payments_session_view(o uuid,identifier uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.giving_sessions;begin
 select * into s from public.giving_sessions where organization_id=o and id=identifier;if not found then raise exception 'Checkout unavailable'using errcode='42501';end if;
 return jsonb_build_object('session',jsonb_build_object('id',s.id,'person_id',s.person_id,'currency',s.currency,'total_minor',s.intended_minor::text,'status',s.status,'expires_at',s.expires_at,'anonymous',s.anonymous_public),'lines',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'amount_minor',l.amount_minor::text,'purpose',private.payments_line_purpose(l),'fund',coalesce(l.route_snapshot->>'fund_label',(select name from public.giving_funds where id=l.fund_id)),'merchant',l.route_snapshot->>'destination_label','tax_eligible',l.tax_eligible)),'[]')from public.giving_session_lines l where l.organization_id=o and l.session_id=s.id),'legs',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'amount_minor',l.amount_minor::text,'status',l.status,'provider',l.route_snapshot->>'provider','gateway_label',(select label from public.giving_gateway_accounts where id=(l.route_snapshot->>'gateway_id')::uuid),'route_label',l.route_snapshot->>'route_label','gate',private.payments_gate(o,l.id))),'[]')from public.giving_transaction_legs l where l.organization_id=o and l.session_id=s.id),'receipt',jsonb_build_object('state','preview_held','date',s.created_at,'reference',s.id,'total_minor',s.intended_minor::text,'payment_method_summary','Not selected — processing held','charitable_minor',(select coalesce(sum(l.amount_minor)filter(where private.payments_line_purpose(l)='charitable_contribution'),0)::text from public.giving_session_lines l where l.organization_id=o and l.session_id=s.id),'non_charitable_minor',(select coalesce(sum(l.amount_minor)filter(where private.payments_line_purpose(l)<>'charitable_contribution'),0)::text from public.giving_session_lines l where l.organization_id=o and l.session_id=s.id),'delivery','held'),'checkout',(select jsonb_build_object('recurring_choice',recurring_choice,'receipt_email',receipt_email)from private.payments_checkout_context where session_id=s.id),'execution','held','message','Payment processing is not yet enabled.');
end$$;
create function private.payments_workspace(a text,o uuid,p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare result jsonb;identifier uuid:=(p->>'id')::uuid;previous public.giving_requests;permission text;g public.giving_gateway_accounts;r public.giving_processor_routes;d public.giving_destinations;sub public.platform_form_submissions;method private.payments_methods;key uuid;begin
 if not private.outreach_verified(auth.uid()) then raise exception 'Verified payment staff required'using errcode='42501';end if;
 if a='context'then return jsonb_build_object('organizations',(select coalesce(jsonb_agg(jsonb_build_object('id',x.id,'name',x.name,'permissions',x.permissions)order by x.name),'[]')from(select id,name,array(select k from unnest(private.payments_permissions())k where private.giving_authorized(id,k))permissions from public.organizations)x where cardinality(x.permissions)>0),'execution','held');end if;
 perform private.giving_lock(o);
 permission:=case a when 'gateway_create'then 'payments.configure'when 'route_create'then 'payments.route'when 'route_bind'then 'payments.route'when 'activation_request'then 'payments.provider.activate'when 'refund_request'then 'payments.refund'when 'void_request'then 'payments.void'when 'recurring_map'then 'payments.recurring.manage'when 'method_remove'then 'payments.configure'else 'payments.view'end;
 perform private.payments_require(o,permission);
 if a='checkout_prepare'then return private.payments_prepare(o,p);
 elsif a='session'then perform private.giving_payload(p,array['id']);return private.payments_session_view(o,identifier);
 elsif a='methods'then perform private.giving_payload(p,array['person_id']);return jsonb_build_object('methods',private.payments_method_summary(o,(p->>'person_id')::uuid),'execution','held');
 elsif a='method_remove'then
 perform private.giving_payload(p,array['id']);update private.payments_methods set status='removed',updated_at=now()where organization_id=o and id=identifier returning id into identifier;if identifier is null then raise exception 'Payment method unavailable'using errcode='42501';end if;
 update private.giving_payment_profiles set reference_status='removed',active=false,updated_at=now()where organization_id=o and logical_method_id=identifier;perform private.giving_audit_event(o,'payments.method.removed',identifier);return jsonb_build_object('id',identifier,'status','removed');
 elsif a='form_checkout'then
 perform private.giving_payload(p,array['submission_id']);select * into sub from public.platform_form_submissions where organization_id=o and id=(p->>'submission_id')::uuid;
 if not found or sub.giving_session_id is null or not private.forms_can(o,'forms.submissions.read',sub.form_id)then raise exception 'Form checkout unavailable'using errcode='42501';end if;
 insert into private.payments_checkout_context(session_id,organization_id,form_version_id)values(sub.giving_session_id,o,sub.version_id)on conflict(session_id)do nothing;return private.payments_session_view(o,sub.giving_session_id);
 elsif a='activation_request'then
 perform private.giving_payload(p,array['id']);select * into g from public.giving_gateway_accounts where organization_id=o and id=identifier;if not found then raise exception 'Gateway unavailable'using errcode='42501';end if;
 perform private.giving_audit_event(o,'payments.activation.attempt',identifier,jsonb_build_object('platform_authority',exists(select 1 from private.payments_platform_authority where user_id=auth.uid() and active and effective_at<=now()and expires_at>now()),'result','held'));
 return jsonb_build_object('enabled',false,'status','held','message','Provider activation requires a separately authorized release.');
 elsif a='gateway_create'then
 perform private.giving_payload(p,array['label','provider','environment','capabilities']);if p->>'provider' not in('nmi','authorize_net','manual','future')or p->>'provider'is null then raise exception 'Supported provider code required';end if;
 if p->>'environment' not in('sandbox','live')or p->>'environment'is null then raise exception 'Explicit environment required';end if;
 if length(btrim(coalesce(p->>'label','')))not between 1 and 120 then raise exception 'Gateway label required';end if;
 insert into public.giving_gateway_accounts(organization_id,provider,label,environment,capabilities)values(o,p->>'provider',p->>'label',p->>'environment',array(select jsonb_array_elements_text(coalesce(p->'capabilities','[]'))))returning id into identifier;
 perform private.giving_audit_event(o,'payments.gateway.created',identifier);return jsonb_build_object('id',identifier,'enabled',false,'configuration_status','missing');
 elsif a='route_create'then
 perform private.giving_payload(p,array['gateway_id','label','provider_route_key','external_processor_id','currency','country','capabilities']);
 select * into g from public.giving_gateway_accounts where organization_id=o and id=(p->>'gateway_id')::uuid;if not found then raise exception 'Gateway unavailable'using errcode='42501';end if;
 if p->>'provider_route_key' !~ '^[A-Za-z][A-Za-z0-9:_-]{0,119}$' or p->>'provider_route_key'is null or (p->>'external_processor_id'is not null and p->>'external_processor_id'!~ '^[A-Za-z0-9:_-]{1,120}$')then raise exception 'Safe non-secret route reference required';end if;
 insert into public.giving_processor_routes(organization_id,gateway_id,label,processor_reference,provider_route_key,external_processor_id,currency,country,environment,capabilities)values(o,g.id,p->>'label',p->>'provider_route_key',p->>'provider_route_key',p->>'external_processor_id',p->>'currency',p->>'country',g.environment,array(select jsonb_array_elements_text(coalesce(p->'capabilities','[]'))))returning id into identifier;
 perform private.giving_audit_event(o,'payments.route.created',identifier);return jsonb_build_object('id',identifier,'payments_enabled',false);
 elsif a='route_bind'then
 perform private.giving_payload(p,array['id','revision','gateway_id','route_id']);select * into d from public.giving_destinations where organization_id=o and id=identifier;
 if not found then raise exception 'Destination unavailable'using errcode='42501';end if;if d.revision<>(p->>'revision')::int or p->>'revision'is null then raise exception 'Merchant route changed; reload before saving'using errcode='PT409';end if;
 select * into r from public.giving_processor_routes where organization_id=o and id=(p->>'route_id')::uuid and gateway_id=(p->>'gateway_id')::uuid and active;
 if not found or r.currency<>d.currency then raise exception 'Same-owner currency route required';end if;
 select * into g from public.giving_gateway_accounts where organization_id=o and id=r.gateway_id;
 update public.giving_destinations set gateway_id=g.id,processor_route_id=r.id,provider=g.provider,revision=revision+1 where organization_id=o and id=d.id;
 perform private.giving_audit_event(o,'payments.route.bound',d.id);return jsonb_build_object('id',d.id,'revision',d.revision+1);
 elsif a in('refund_request','void_request')then
 perform private.giving_payload(p,array['request_key','leg_id','amount_minor','reason']);key:=(p->>'request_key')::uuid;if key is null then raise exception 'Refund idempotency key required';end if;
 select * into previous from public.giving_requests where organization_id=o and operation='payments.'||a and request_key=key;
 if found then if previous.payload<>p then raise exception 'Refund idempotency conflict'using errcode='PT409';end if;return previous.result;end if;
 if length(btrim(coalesce(p->>'reason','')))<5 or p->>'amount_minor'!~ '^[0-9]{1,13}$' then raise exception 'Exact amount and review reason required';end if;
 result:=private.giving_financial_action(o,'refund_request',p||jsonb_build_object('kind',case when a='void_request'then 'void'else 'refund'end));
 perform private.giving_audit_event(o,'payments.'||a,(result->>'id')::uuid,jsonb_build_object('execution','held'));
 result:=jsonb_build_object('id',result->'id','status','requested','execution','held');insert into public.giving_requests values(o,'payments.'||a,key,p,result,now());return result;
 elsif a='recurring_map'then
 perform private.giving_payload(p,array['id']);if not exists(select 1 from public.giving_recurring_instructions where organization_id=o and id=identifier)then raise exception 'Recurring plan unavailable'using errcode='42501';end if;
 insert into private.payments_recurring_routes(organization_id,instruction_id,route_id)select o,identifier,(route_snapshot->>'processor_route_id')::uuid from public.giving_recurring_lines where organization_id=o and instruction_id=identifier group by(route_snapshot->>'processor_route_id')::uuid on conflict do nothing;
 perform private.giving_audit_event(o,'payments.recurring.mapped',identifier);return jsonb_build_object('instruction_id',identifier,'routes',(select count(*)from private.payments_recurring_routes where instruction_id=identifier),'execution','held');
 elsif a='configuration'then
 perform private.giving_payload(p,array[]::text[]);
 return jsonb_build_object('gateways',(select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'provider',g.provider,'label',g.label,'environment',g.environment,'enabled',g.enabled,'status',g.configuration_status,'capabilities',g.capabilities,'last_verified',g.last_verified_at,'credential_status',case when exists(select 1 from private.payments_gateway_bindings where gateway_id=g.id)then 'Configured'else 'Missing'end)order by g.label),'[]')from public.giving_gateway_accounts g where organization_id=o),'routes',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'gateway_id',r.gateway_id,'label',r.label,'currency',r.currency,'country',r.country,'environment',r.environment,'enabled',r.payments_enabled,'capabilities',r.capabilities)order by r.label),'[]')from public.giving_processor_routes r where organization_id=o),'destinations',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'label',d.merchant_label,'gateway_id',d.gateway_id,'route_id',d.processor_route_id,'currency',d.currency,'revision',d.revision)),'[]')from public.giving_destinations d where organization_id=o),'funds',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'name',name,'destination_id',destination_id,'tax_eligible',tax_eligible)),'[]')from public.giving_funds where organization_id=o and status='active'),'sessions',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'total_minor',intended_minor::text,'currency',currency,'status',status)order by created_at desc),'[]')from public.giving_sessions where organization_id=o and source='native_checkout'),'global_enabled',false,'message','Payment processing is not yet enabled.');
 else raise exception 'Unknown payment action';end if;
end$$;
create function private.payments_service(a text,o uuid,p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare l public.giving_transaction_legs;g public.giving_gateway_accounts;op private.payments_operations;profile private.giving_payment_profiles;method private.payments_methods;existing private.payments_webhooks;identifier uuid;token uuid;digest text;event_status text;instruction public.giving_recurring_instructions;result jsonb;begin
 if current_setting('role',true)<>'service_role'then raise exception 'Payment service authority required'using errcode='42501';end if;
 perform private.giving_lock(o);
 if a='operation_prepare'then
 perform private.giving_payload(p,array['request_key','leg_id','operation','amount_minor','refund_id']);
 select * into l from public.giving_transaction_legs where organization_id=o and id=(p->>'leg_id')::uuid;if not found then raise exception 'Transaction unavailable'using errcode='42501';end if;
 if p->>'request_key'is null or p->>'amount_minor'!~ '^[0-9]{1,13}$' or (p->>'amount_minor')::bigint not between 1 and l.amount_minor then raise exception 'Bound operation identity/amount required';end if;
 if p->>'operation'in('refund','void')and not exists(select 1 from public.giving_refunds where organization_id=o and id=(p->>'refund_id')::uuid and leg_id=l.id and kind=p->>'operation'and amount_minor=(p->>'amount_minor')::bigint and status='requested')then raise exception 'Original held refund/void request required';end if;digest:=encode(sha256(convert_to(p::text,'UTF8')),'hex');select * into op from private.payments_operations where organization_id=o and operation=p->>'operation' and request_key=(p->>'request_key')::uuid;
 if found then if op.payload_digest<>digest then raise exception 'Provider operation idempotency conflict'using errcode='PT409';end if;return jsonb_build_object('id',op.id,'execution','held');end if;
 insert into private.payments_operations(organization_id,leg_id,gateway_id,operation,request_key,payload_digest,amount_minor,refund_id)values(o,l.id,(l.route_snapshot->>'gateway_id')::uuid,p->>'operation',(p->>'request_key')::uuid,digest,(p->>'amount_minor')::bigint,(p->>'refund_id')::uuid)returning id into identifier;
 insert into private.payments_journal(organization_id,operation_id,provider,route_id,state,failure_category)values(o,identifier,l.route_snapshot->>'provider',(l.route_snapshot->>'processor_route_id')::uuid,'held','configuration_error');return jsonb_build_object('id',identifier,'execution','held');
 elsif a='operation_claim'then
 perform private.giving_payload(p,array['id']);select * into op from private.payments_operations where organization_id=o and id=(p->>'id')::uuid;
 if not found then raise exception 'Operation unavailable'using errcode='42501';end if;
 if op.lease_token is not null then return jsonb_build_object('claimed',false,'execution','held');end if;token:=gen_random_uuid();
 update private.payments_operations set lease_token=token,lease_created_at=clock_timestamp()where id=op.id and lease_token is null;
 select * into l from public.giving_transaction_legs where organization_id=o and id=op.leg_id;
 insert into private.payments_journal(organization_id,operation_id,provider,route_id,state,failure_category)values(o,op.id,l.route_snapshot->>'provider',(l.route_snapshot->>'processor_route_id')::uuid,'claimed','configuration_error');
 return jsonb_build_object('claimed',true,'lease_token',token,'execution','held','gate',private.payments_gate(o,l.id));
 elsif a='synthetic_method_attach'then
 perform private.giving_payload(p,array['person_id','logical_method_id','gateway_id','route_ids','customer_reference','payment_reference','brand','last4','expiry_month','expiry_year','billing_name']);
 if p->>'customer_reference'!~ '^synth:[A-Za-z0-9:_-]{1,120}$'or p->>'payment_reference'!~ '^synth:[A-Za-z0-9:_-]{1,120}$'or p->>'customer_reference'is null or p->>'payment_reference'is null then raise exception 'GIV-3A accepts synthetic references only';end if;
 perform private.giving_identity(o,(p->>'person_id')::uuid,null);
 select * into g from public.giving_gateway_accounts where organization_id=o and id=(p->>'gateway_id')::uuid and environment='sandbox';if not found then raise exception 'Synthetic sandbox account required';end if;
 if jsonb_typeof(p->'route_ids')<>'array' or jsonb_array_length(p->'route_ids')not between 1 and 30 or exists(select 1 from jsonb_array_elements_text(p->'route_ids')x where not exists(select 1 from public.giving_processor_routes where organization_id=o and gateway_id=g.id and id=x::uuid and environment=g.environment))then raise exception 'Explicit same-gateway route scope required';end if;
 select * into profile from private.giving_payment_profiles where organization_id=o and gateway_id=g.id and provider_customer_reference=p->>'customer_reference'and provider_payment_reference=p->>'payment_reference';
 if found then
 select * into method from private.payments_methods where organization_id=o and id=profile.logical_method_id;
 if not found or method.status='removed' or profile.person_id<>(p->>'person_id')::uuid or profile.logical_method_id is null or (p->>'logical_method_id'is not null and profile.logical_method_id is distinct from(p->>'logical_method_id')::uuid) or method.brand is distinct from p->>'brand' or method.last4 is distinct from p->>'last4' or method.expiry_month is distinct from(p->>'expiry_month')::int or method.expiry_year is distinct from(p->>'expiry_year')::int or method.billing_name is distinct from p->>'billing_name' or (select array_agg(route_id::text order by route_id::text)from private.payments_token_routes where profile_id=profile.id)is distinct from(select array_agg(x order by x)from jsonb_array_elements_text(p->'route_ids')x) then raise exception 'Method identity or scope reuse conflict';end if;
 return jsonb_build_object('id',profile.logical_method_id,'status','held');end if;
 identifier:=(p->>'logical_method_id')::uuid;
 if identifier is null then insert into private.payments_methods(organization_id,person_id,brand,last4,expiry_month,expiry_year,billing_name)values(o,(p->>'person_id')::uuid,p->>'brand',p->>'last4',(p->>'expiry_month')::int,(p->>'expiry_year')::int,p->>'billing_name')returning id into identifier;
 else select * into method from private.payments_methods where organization_id=o and id=identifier and person_id=(p->>'person_id')::uuid and brand=p->>'brand'and last4=p->>'last4'and status<>'removed';if not found then raise exception 'Logical method owner/descriptor mismatch';end if;end if;
 insert into private.payments_customers(organization_id,person_id,gateway_id,environment,provider_customer_reference)values(o,(p->>'person_id')::uuid,g.id,g.environment,p->>'customer_reference')on conflict(organization_id,gateway_id,environment,person_id)do nothing;
 if not exists(select 1 from private.payments_customers where organization_id=o and person_id=(p->>'person_id')::uuid and gateway_id=g.id and environment=g.environment and provider_customer_reference=p->>'customer_reference')then raise exception 'Customer profile mismatch';end if;
 insert into private.giving_payment_profiles(organization_id,person_id,gateway_id,provider_customer_reference,provider_payment_reference,method,descriptor,active,logical_method_id,environment)values(o,(p->>'person_id')::uuid,g.id,p->>'customer_reference',p->>'payment_reference','card',(p->>'brand')||' ending '||(p->>'last4'),false,identifier,g.environment)returning id into token;
 insert into private.payments_token_routes(organization_id,profile_id,gateway_id,route_id)select o,token,g.id,x::uuid from jsonb_array_elements_text(p->'route_ids')x;
 perform private.giving_audit_event(o,'payments.method.attached',identifier,jsonb_build_object('status','held'));return jsonb_build_object('id',identifier,'status','held');
 elsif a='synthetic_webhook'then
 perform private.giving_payload(p,array['gateway_id','route_id','leg_id','event_reference','body_digest','normalized_status','signature_verified']);
 if p->'signature_verified'<>'true'::jsonb or p->>'signature_verified'is null then raise exception 'Verified signature required';end if;
 select * into l from public.giving_transaction_legs where organization_id=o and id=(p->>'leg_id')::uuid;
 if not found or l.route_snapshot->>'gateway_id'<>p->>'gateway_id' or l.route_snapshot->>'processor_route_id'<>p->>'route_id' or l.route_snapshot->>'environment'<>'sandbox'then raise exception 'Webhook transaction/account/route mismatch';end if;
 select * into existing from private.payments_webhooks where gateway_id=(p->>'gateway_id')::uuid and event_reference=p->>'event_reference';
 if found then if existing.body_digest<>p->>'body_digest'or existing.leg_id<>l.id or existing.normalized_status<>p->>'normalized_status'then raise exception 'Webhook replay conflict';end if;return jsonb_build_object('id',existing.id,'duplicate',true,'reconciliation','held');end if;
 insert into private.payments_webhooks(organization_id,gateway_id,route_id,leg_id,event_reference,body_digest,normalized_status)values(o,(p->>'gateway_id')::uuid,(p->>'route_id')::uuid,l.id,p->>'event_reference',p->>'body_digest',p->>'normalized_status')returning id into identifier;
 perform private.giving_audit_event(o,'payments.webhook.normalized',identifier,jsonb_build_object('reconciliation','held','dispute',p->>'normalized_status'='disputed'));return jsonb_build_object('id',identifier,'duplicate',false,'reconciliation','held');
 elsif a='synthetic_settlement'then
 perform private.giving_payload(p,array['gateway_id','route_id','batch_reference','settlement_date','currency','gross_minor','fee_minor','net_minor','transaction_count']);
 select * into g from public.giving_gateway_accounts where organization_id=o and id=(p->>'gateway_id')::uuid and environment='sandbox';if not found or not exists(select 1 from public.giving_processor_routes where organization_id=o and id=(p->>'route_id')::uuid and gateway_id=g.id and currency=p->>'currency')then raise exception 'Sandbox settlement binding required';end if;
 digest:=encode(sha256(convert_to(p::text,'UTF8')),'hex');select id into identifier from private.payments_settlements where gateway_id=g.id and route_id=(p->>'route_id')::uuid and provider_batch_reference=p->>'batch_reference';if identifier is not null then if not exists(select 1 from private.payments_settlements where id=identifier and payload_digest=digest)then raise exception 'Settlement replay conflict'using errcode='PT409';end if;return jsonb_build_object('id',identifier,'execution','held');end if;
 insert into private.payments_settlements(organization_id,gateway_id,route_id,provider_batch_reference,payload_digest,settlement_date,currency,gross_minor,fee_minor,net_minor,transaction_count)values(o,g.id,(p->>'route_id')::uuid,p->>'batch_reference',digest,(p->>'settlement_date')::date,p->>'currency',(p->>'gross_minor')::bigint,(p->>'fee_minor')::bigint,(p->>'net_minor')::bigint,(p->>'transaction_count')::int)returning id into identifier;return jsonb_build_object('id',identifier,'execution','held');
 elsif a='recurring_claim'then
 perform private.giving_payload(p,array['id','scheduled_at']);select * into instruction from public.giving_recurring_instructions where organization_id=o and id=(p->>'id')::uuid and status in('draft','active','paused');
 if not found or (p->>'scheduled_at')::timestamptz<>instruction.next_run_at then raise exception 'Canonical scheduled time required';end if;
 insert into private.payments_recurring_jobs(organization_id,instruction_id,scheduled_at)values(o,instruction.id,instruction.next_run_at)on conflict(instruction_id,scheduled_at)do nothing returning id into identifier;
 if identifier is null then return jsonb_build_object('claimed',false,'execution','held');end if;perform private.giving_audit_event(o,'payments.recurring.lease.held',instruction.id);return jsonb_build_object('claimed',true,'id',identifier,'execution','held');
 else raise exception 'Unknown payment service action';end if;
end$$;
create function private.payments_donor(a text,o uuid,p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare person uuid;identifier uuid:=(p->>'id')::uuid;begin
 if not private.outreach_verified(auth.uid())then raise exception 'Verified financial owner required'using errcode='42501';end if;perform private.giving_lock(o);
 select person_id into person from private.giving_donor_account_links where organization_id=o and user_id=auth.uid()and active;if person is null then raise exception 'Reviewed financial ownership required'using errcode='42501';end if;
 if a='methods'then perform private.giving_payload(p,array[]::text[]);return jsonb_build_object('methods',private.payments_method_summary(o,person),'execution','held');
 elsif a='session'then perform private.giving_payload(p,array['id']);if not exists(select 1 from public.giving_sessions where organization_id=o and id=identifier and person_id=person)then raise exception 'Checkout unavailable'using errcode='42501';end if;return private.payments_session_view(o,identifier);
 elsif a='method_remove'then perform private.giving_payload(p,array['id']);update private.payments_methods set status='removed',updated_at=now()where organization_id=o and id=identifier and person_id=person returning id into identifier;if identifier is null then raise exception 'Method unavailable'using errcode='42501';end if;update private.giving_payment_profiles set active=false,reference_status='removed'where organization_id=o and logical_method_id=identifier;perform private.giving_audit_event(o,'payments.method.removed',identifier);return jsonb_build_object('id',identifier,'status','removed');
 else raise exception 'Unknown donor action';end if;end$$;
-- Existing Forms payment lines gain immutable purpose/version classification at insertion, not a second ledger.
create or replace function private.forms_giving_classification()returns trigger language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare classification text;v uuid;begin
 select pay.classification,i.version_id into classification,v from public.giving_sessions gs join public.platform_forms f on gs.guest_reference='form:'||f.id::text and f.organization_id=gs.organization_id join public.platform_form_instances i on i.form_id=f.id join public.platform_form_payments pay on pay.version_id=i.version_id where gs.id=new.session_id and gs.source='platform_form';
 if classification is not null then new.payment_purpose:=case classification when 'donation'then 'charitable_contribution'when 'purchase'then 'merchandise'else classification end;new.form_version_id:=v;if classification<>'donation'then new.tax_eligible:=false;end if;end if;return new;end$$;
-- New online intents cannot bypass the stage gate through the old trusted financial finalizer.
do $$declare body text;needle text:='if not found then raise exception ''Session unavailable'';end if;';begin
 body:=pg_get_functiondef('private.giving_post_session(uuid,uuid)'::regprocedure);
 if position(needle in body)=0 then raise exception 'Accepted Giving finalizer contract changed';end if;
 body:=replace(body,needle,needle||E'\n if s.source in(''native_checkout'',''platform_form'')then raise exception ''Payment processing is not yet enabled.'' using errcode=''42501'';end if;');execute body;
end$$;
create function public.payments_workspace(p_action text,p_org uuid default null,p_payload jsonb default '{}')returns jsonb language sql security invoker set search_path=''as $$select private.payments_workspace(p_action,p_org,p_payload)$$;
create function public.payments_service(p_action text,p_org uuid,p_payload jsonb default '{}')returns jsonb language sql security invoker set search_path=''as $$select private.payments_service(p_action,p_org,p_payload)$$;
create function public.payments_donor(p_action text,p_org uuid,p_payload jsonb default '{}')returns jsonb language sql security invoker set search_path=''as $$select private.payments_donor(p_action,p_org,p_payload)$$;
do $$declare r record;begin for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private'and p.proname like 'payments_%'loop execute format('revoke all on function %s from public,anon,authenticated,service_role',r.signature);end loop;end$$;
revoke all on function public.payments_workspace(text,uuid,jsonb),public.payments_service(text,uuid,jsonb),public.payments_donor(text,uuid,jsonb)from public,anon,authenticated,service_role;
grant execute on function public.payments_workspace(text,uuid,jsonb),private.payments_workspace(text,uuid,jsonb),public.payments_donor(text,uuid,jsonb),private.payments_donor(text,uuid,jsonb)to authenticated;
grant execute on function public.payments_service(text,uuid,jsonb),private.payments_service(text,uuid,jsonb)to service_role;
